from __future__ import annotations

import asyncio
from dataclasses import dataclass, field
import heapq
import itertools
from typing import Any, Awaitable, Callable, Dict, List, Optional, Set, Tuple


@dataclass(order=True)
class _WorkItem:
    neg_priority: int
    seq: int
    coro_func: Callable[..., Awaitable[Any]] = field(compare=False)
    args: Tuple[Any, ...] = field(compare=False)
    kwargs: Dict[str, Any] = field(compare=False)
    future: asyncio.Future[Any] = field(compare=False)


async def _invoke(
    coro_func: Callable[..., Awaitable[Any]],
    args: Tuple[Any, ...],
    kwargs: Dict[str, Any],
) -> Any:
    return await coro_func(*args, **kwargs)


class AsyncWorkerPool:
    """Asynchronous priority worker pool built on standard asyncio."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be a positive integer")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be a non-negative integer")

        self._concurrency: int = concurrency
        self._max_queue_size: int = max_queue_size

        self._heap: List[_WorkItem] = []
        self._seq = itertools.count()

        self._lock: Optional[asyncio.Lock] = None
        self._not_empty: Optional[asyncio.Condition] = None
        self._not_full: Optional[asyncio.Condition] = None

        self._workers: List[asyncio.Task[None]] = []
        self._active: Dict[asyncio.Task[Any], asyncio.Future[Any]] = {}

        self._started: bool = False
        self._shutting_down: bool = False
        self._force_cancel: bool = False

    def _ensure_primitives(
        self,
    ) -> Tuple[asyncio.Lock, asyncio.Condition, asyncio.Condition]:
        if self._lock is None:
            self._lock = asyncio.Lock()
            self._not_empty = asyncio.Condition(self._lock)
            self._not_full = asyncio.Condition(self._lock)
        assert self._not_empty is not None and self._not_full is not None
        return self._lock, self._not_empty, self._not_full

    async def start(self) -> None:
        """Spawn worker tasks."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return

        self._ensure_primitives()
        self._started = True
        self._workers = [
            asyncio.create_task(self._worker_loop(), name=f"async-worker-{i}")
            for i in range(self._concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Awaitable[Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future[Any]:
        """Enqueue a coroutine function to be executed by the pool workers."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if not callable(coro_func):
            raise TypeError("coro_func must be callable")

        lock, not_empty, not_full = self._ensure_primitives()
        loop = asyncio.get_running_loop()

        async with lock:
            while (
                not self._shutting_down
                and self._max_queue_size > 0
                and len(self._heap) >= self._max_queue_size
            ):
                try:
                    await not_full.wait()
                except asyncio.CancelledError:
                    if (
                        self._max_queue_size == 0
                        or len(self._heap) < self._max_queue_size
                    ):
                        not_full.notify()
                    raise

            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            future: asyncio.Future[Any] = loop.create_future()
            item = _WorkItem(
                neg_priority=-priority,
                seq=next(self._seq),
                coro_func=coro_func,
                args=args,
                kwargs=kwargs,
                future=future,
            )
            heapq.heappush(self._heap, item)
            not_empty.notify()
            return future

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        """Shut down the worker pool.

        If drain=True, waits for all currently enqueued tasks to complete
        before stopping workers. If drain=False, cancels all queued and
        currently executing tasks immediately. Respects optional timeout.
        """
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must be non-negative or None")

        lock, not_empty, not_full = self._ensure_primitives()

        async with lock:
            self._shutting_down = True
            if not drain:
                self._force_cancel = True
                self._cancel_queued_items_locked()
            not_empty.notify_all()
            not_full.notify_all()

        workers = [w for w in self._workers if not w.done()]

        if not workers:
            async with lock:
                self._cancel_queued_items_locked()
                not_full.notify_all()
            self._workers.clear()
            return

        if not drain:
            self._cancel_active_and_workers(workers)
            done, pending = await asyncio.wait(workers, timeout=timeout)
            self._consume_worker_exceptions(done)
            if not pending:
                self._workers.clear()
            return

        done, pending = await asyncio.wait(workers, timeout=timeout)
        self._consume_worker_exceptions(done)

        if not pending:
            self._workers.clear()
            return

        async with lock:
            self._force_cancel = True
            self._cancel_queued_items_locked()
            not_empty.notify_all()
            not_full.notify_all()

        self._cancel_active_and_workers(list(pending))
        cleanup_timeout = (
            min(0.1, timeout) if (timeout is not None and timeout > 0) else 0.05
        )
        done_after_cancel, still_pending = await asyncio.wait(
            pending, timeout=cleanup_timeout
        )
        self._consume_worker_exceptions(done_after_cancel)
        if not still_pending:
            self._workers.clear()

    def _cancel_queued_items_locked(self) -> None:
        while self._heap:
            item = heapq.heappop(self._heap)
            if not item.future.done():
                item.future.cancel()

    def _cancel_active_and_workers(
        self, workers: List[asyncio.Task[None]]
    ) -> None:
        for exec_task, fut in list(self._active.items()):
            if not fut.done():
                fut.cancel()
            if not exec_task.done():
                exec_task.cancel()
        for worker in workers:
            if not worker.done():
                worker.cancel()

    @staticmethod
    def _consume_worker_exceptions(workers: Set[asyncio.Task[None]]) -> None:
        for worker in workers:
            if not worker.cancelled():
                worker.exception()

    async def _worker_loop(self) -> None:
        lock, not_empty, not_full = self._ensure_primitives()

        while True:
            async with lock:
                while (
                    not self._heap
                    and not self._shutting_down
                    and not self._force_cancel
                ):
                    try:
                        await not_empty.wait()
                    except asyncio.CancelledError:
                        if (
                            self._heap
                            or self._shutting_down
                            or self._force_cancel
                        ):
                            not_empty.notify()
                        raise

                if self._force_cancel:
                    return

                if not self._heap and self._shutting_down:
                    return

                item = heapq.heappop(self._heap)
                not_full.notify()

            if item.future.cancelled():
                continue

            await self._execute_item(item)

    async def _execute_item(self, item: _WorkItem) -> None:
        exec_task: asyncio.Task[Any] = asyncio.create_task(
            _invoke(item.coro_func, item.args, item.kwargs)
        )
        self._active[exec_task] = item.future

        def _on_future_done(fut: asyncio.Future[Any]) -> None:
            if fut.cancelled() and not exec_task.done():
                exec_task.cancel()

        item.future.add_done_callback(_on_future_done)

        try:
            try:
                await asyncio.wait({exec_task})
            except asyncio.CancelledError:
                if not exec_task.done():
                    exec_task.cancel()
                    try:
                        await exec_task
                    except BaseException:
                        pass
                if not item.future.done():
                    item.future.cancel()
                raise

            if exec_task.cancelled():
                if not item.future.done():
                    item.future.cancel()
            else:
                exc = exec_task.exception()
                if exc is not None:
                    if not item.future.done():
                        if isinstance(exc, StopIteration):
                            exc = RuntimeError("Coroutine raised StopIteration")
                        item.future.set_exception(exc)
                else:
                    result = exec_task.result()
                    if not item.future.done():
                        item.future.set_result(result)
        finally:
            item.future.remove_done_callback(_on_future_done)
            self._active.pop(exec_task, None)

    async def __aenter__(self) -> AsyncWorkerPool:
        await self.start()
        return self

    async def __aexit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        await self.shutdown(drain=True)
