import ast
from typing import Dict, Iterable, List, Optional, Set, Tuple

_TRY_NODES = tuple(
    t for t in (ast.Try, getattr(ast, "TryStar", None)) if t is not None
)
_MATCH_NODE = getattr(ast, "Match", None)
_MATCH_AS = getattr(ast, "MatchAs", None)
_MATCH_STAR = getattr(ast, "MatchStar", None)
_MATCH_MAPPING = getattr(ast, "MatchMapping", None)
_TYPE_ALIAS_NODE = getattr(ast, "TypeAlias", None)

_PRESERVED_DUNDER_FUNCS = frozenset({"__getattr__", "__dir__"})


def _import_bound_name(node: ast.AST, alias: ast.alias) -> str:
    if alias.asname:
        return alias.asname
    if isinstance(node, ast.Import):
        return alias.name.split(".", 1)[0]
    return alias.name


def _collect_target_names(target: ast.AST) -> Set[str]:
    names: Set[str] = set()
    if isinstance(target, ast.Name):
        names.add(target.id)
    elif isinstance(target, (ast.Tuple, ast.List)):
        for elt in target.elts:
            names |= _collect_target_names(elt)
    elif isinstance(target, ast.Starred):
        names |= _collect_target_names(target.value)
    return names


def _collect_pattern_names(pattern: ast.AST) -> Set[str]:
    names: Set[str] = set()
    for sub in ast.walk(pattern):
        if _MATCH_AS is not None and isinstance(sub, _MATCH_AS) and sub.name:
            names.add(sub.name)
        elif _MATCH_STAR is not None and isinstance(sub, _MATCH_STAR) and sub.name:
            names.add(sub.name)
        elif _MATCH_MAPPING is not None and isinstance(sub, _MATCH_MAPPING) and sub.rest:
            names.add(sub.rest)
    return names


def _collect_param_names(args: ast.arguments) -> Set[str]:
    names: Set[str] = set()
    for arg in list(args.posonlyargs) + list(args.args) + list(args.kwonlyargs):
        names.add(arg.arg)
    if args.vararg:
        names.add(args.vararg.arg)
    if args.kwarg:
        names.add(args.kwarg.arg)
    return names


def _collect_type_param_names(node: ast.AST) -> Set[str]:
    names: Set[str] = set()
    for tp in getattr(node, "type_params", ()):
        name = getattr(tp, "name", None)
        if isinstance(name, str):
            names.add(name)
    return names


def _collect_walrus_targets(node: ast.AST) -> Set[str]:
    names: Set[str] = set()
    if isinstance(node, ast.NamedExpr):
        names.add(node.target.id)
        names |= _collect_walrus_targets(node.value)
        return names
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        for dec in node.decorator_list:
            names |= _collect_walrus_targets(dec)
        for d in node.args.defaults:
            names |= _collect_walrus_targets(d)
        for d in node.args.kw_defaults:
            if d is not None:
                names |= _collect_walrus_targets(d)
        return names
    if isinstance(node, ast.ClassDef):
        for dec in node.decorator_list:
            names |= _collect_walrus_targets(dec)
        for base in node.bases:
            names |= _collect_walrus_targets(base)
        for kw in node.keywords:
            names |= _collect_walrus_targets(kw.value)
        return names
    if isinstance(node, ast.Lambda):
        for d in node.args.defaults:
            names |= _collect_walrus_targets(d)
        for d in node.args.kw_defaults:
            if d is not None:
                names |= _collect_walrus_targets(d)
        return names
    for child in ast.iter_child_nodes(node):
        names |= _collect_walrus_targets(child)
    return names


def _collect_scope_bindings(
    stmts: Iterable[ast.stmt],
) -> Tuple[Set[str], Set[str], Set[str]]:
    """Collect (local_bindings, global_names, nonlocal_names) for a function body."""
    bindings: Set[str] = set()
    globals_: Set[str] = set()
    nonlocals_: Set[str] = set()

    def walk_node(node: ast.AST) -> None:
        if isinstance(node, ast.Global):
            globals_.update(node.names)
            return
        if isinstance(node, ast.Nonlocal):
            nonlocals_.update(node.names)
            return
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            bindings.add(node.name)
            bindings.update(_collect_walrus_targets(node))
            return
        if isinstance(node, ast.ClassDef):
            bindings.add(node.name)
            bindings.update(_collect_walrus_targets(node))
            return
        if isinstance(node, ast.Lambda):
            bindings.update(_collect_walrus_targets(node))
            return
        if isinstance(
            node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)
        ):
            bindings.update(_collect_walrus_targets(node))
            return
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                if alias.name != "*":
                    bindings.add(_import_bound_name(node, alias))
            return
        if _TYPE_ALIAS_NODE is not None and isinstance(node, _TYPE_ALIAS_NODE):
            bindings.add(node.name.id)
            return
        if isinstance(node, ast.ExceptHandler):
            if node.name:
                bindings.add(node.name)
            if node.type is not None:
                walk_node(node.type)
            for s in node.body:
                walk_node(s)
            return
        if _MATCH_NODE is not None and isinstance(node, _MATCH_NODE):
            walk_node(node.subject)
            for case in node.cases:
                bindings.update(_collect_pattern_names(case.pattern))
                if case.guard is not None:
                    walk_node(case.guard)
                for s in case.body:
                    walk_node(s)
            return
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            bindings.add(node.id)
            return
        for child in ast.iter_child_nodes(node):
            walk_node(child)

    for stmt in stmts:
        walk_node(stmt)

    return bindings - globals_ - nonlocals_, globals_, nonlocals_


def _is_named_attr_or_name(node: ast.AST, target: str) -> bool:
    if isinstance(node, ast.Name) and node.id == target:
        return True
    if isinstance(node, ast.Attribute) and node.attr == target:
        return True
    return False


def _free_refs_in_type_params(node: ast.AST) -> Tuple[Set[str], Set[str]]:
    tp_names = _collect_type_param_names(node)
    refs: Set[str] = set()
    for tp in getattr(node, "type_params", ()):
        for child in ast.iter_child_nodes(tp):
            refs |= _free_refs(child, in_annotation=True)
    return refs - tp_names, tp_names


def _function_parts_refs(
    node: ast.AST,
) -> Tuple[Set[str], Set[str], Set[str]]:
    assert isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    tp_refs, tp_names = _free_refs_in_type_params(node)

    outer_refs: Set[str] = set(tp_refs)
    for dec in node.decorator_list:
        outer_refs |= _free_refs(dec)
    for d in node.args.defaults:
        outer_refs |= _free_refs(d)
    for d in node.args.kw_defaults:
        if d is not None:
            outer_refs |= _free_refs(d)

    ann_refs: Set[str] = set()
    all_args = (
        list(node.args.posonlyargs)
        + list(node.args.args)
        + list(node.args.kwonlyargs)
    )
    if node.args.vararg:
        all_args.append(node.args.vararg)
    if node.args.kwarg:
        all_args.append(node.args.kwarg)
    for arg in all_args:
        if arg.annotation is not None:
            ann_refs |= _free_refs(arg.annotation, in_annotation=True)
    if node.returns is not None:
        ann_refs |= _free_refs(node.returns, in_annotation=True)
    outer_refs |= ann_refs - tp_names

    param_names = _collect_param_names(node.args)
    body_locals, globals_, nonlocals_ = _collect_scope_bindings(node.body)
    all_locals = (param_names | body_locals | tp_names) - globals_ - nonlocals_

    body_refs: Set[str] = set()
    for stmt in node.body:
        body_refs |= _free_refs(stmt)
    body_free_refs = (body_refs | nonlocals_) - all_locals

    return outer_refs, body_free_refs, tp_names


def _class_direct_bindings(stmt: ast.stmt) -> Set[str]:
    if isinstance(stmt, ast.Assign):
        names: Set[str] = set()
        for t in stmt.targets:
            names |= _collect_target_names(t)
        return names
    if isinstance(stmt, ast.AnnAssign) and stmt.value is not None:
        return _collect_target_names(stmt.target)
    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        return {stmt.name}
    if isinstance(stmt, (ast.Import, ast.ImportFrom)):
        return {
            _import_bound_name(stmt, a) for a in stmt.names if a.name != "*"
        }
    if _TYPE_ALIAS_NODE is not None and isinstance(stmt, _TYPE_ALIAS_NODE):
        return {stmt.name.id}
    return set()


def _class_parts_refs(node: ast.ClassDef) -> Tuple[Set[str], Set[str], Set[str]]:
    tp_refs, tp_names = _free_refs_in_type_params(node)
    header_refs: Set[str] = set(tp_refs)
    for dec in node.decorator_list:
        header_refs |= _free_refs(dec)
    for base in node.bases:
        header_refs |= _free_refs(base) - tp_names
    for kw in node.keywords:
        header_refs |= _free_refs(kw.value) - tp_names

    body_refs: Set[str] = set()
    class_locals: Set[str] = set(tp_names)
    for stmt in node.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            outer_r, body_r, _ = _function_parts_refs(stmt)
            body_refs |= outer_r - class_locals
            body_refs |= body_r - tp_names
            class_locals.add(stmt.name)
        elif isinstance(stmt, ast.ClassDef):
            nested_hdr, nested_body, _ = _class_parts_refs(stmt)
            body_refs |= nested_hdr - class_locals
            body_refs |= nested_body - tp_names
            class_locals.add(stmt.name)
        else:
            body_refs |= _free_refs(stmt) - class_locals
            class_locals |= _class_direct_bindings(stmt)
    return header_refs, body_refs, tp_names


def _free_refs(node: ast.AST, in_annotation: bool = False) -> Set[str]:
    if isinstance(node, ast.Name):
        if isinstance(node.ctx, (ast.Load, ast.Del)):
            return {node.id}
        return set()

    if isinstance(node, ast.Constant):
        if in_annotation and isinstance(node.value, str):
            try:
                parsed = ast.parse(node.value, mode="eval")
            except SyntaxError:
                return set()
            return _free_refs(parsed.body, in_annotation=True)
        return set()

    if isinstance(node, ast.Subscript) and in_annotation:
        if _is_named_attr_or_name(node.value, "Literal"):
            return _free_refs(node.value, in_annotation=True) | _free_refs(
                node.slice, in_annotation=False
            )
        if _is_named_attr_or_name(node.value, "Annotated"):
            refs = _free_refs(node.value, in_annotation=True)
            if isinstance(node.slice, ast.Tuple) and node.slice.elts:
                refs |= _free_refs(node.slice.elts[0], in_annotation=True)
                for meta in node.slice.elts[1:]:
                    refs |= _free_refs(meta, in_annotation=False)
            else:
                refs |= _free_refs(node.slice, in_annotation=True)
            return refs
        return _free_refs(node.value, in_annotation=True) | _free_refs(
            node.slice, in_annotation=True
        )

    if isinstance(node, (ast.Import, ast.ImportFrom)):
        return set()

    if isinstance(node, ast.AugAssign):
        refs = _free_refs(node.target) | _free_refs(node.value)
        if isinstance(node.target, ast.Name):
            refs.add(node.target.id)
        return refs

    if isinstance(node, ast.AnnAssign):
        refs = _free_refs(node.target) | _free_refs(
            node.annotation, in_annotation=True
        )
        if node.value is not None:
            refs |= _free_refs(node.value)
        return refs

    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        outer_refs, body_free_refs, _ = _function_parts_refs(node)
        return outer_refs | body_free_refs

    if isinstance(node, ast.Lambda):
        outer_refs: Set[str] = set()
        for d in node.args.defaults:
            outer_refs |= _free_refs(d)
        for d in node.args.kw_defaults:
            if d is not None:
                outer_refs |= _free_refs(d)
        param_names = _collect_param_names(node.args)
        return outer_refs | (_free_refs(node.body) - param_names)

    if isinstance(
        node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)
    ):
        outer_refs = _free_refs(node.generators[0].iter)
        comp_locals: Set[str] = set()
        inner_refs: Set[str] = set()
        for idx, gen in enumerate(node.generators):
            if idx > 0:
                inner_refs |= _free_refs(gen.iter) - comp_locals
            inner_refs |= _free_refs(gen.target) - comp_locals
            comp_locals |= _collect_target_names(gen.target)
            for if_expr in gen.ifs:
                inner_refs |= _free_refs(if_expr) - comp_locals
        if isinstance(node, ast.DictComp):
            inner_refs |= (
                _free_refs(node.key) | _free_refs(node.value)
            ) - comp_locals
        else:
            inner_refs |= _free_refs(node.elt) - comp_locals
        return outer_refs | inner_refs

    if isinstance(node, ast.ClassDef):
        header_refs, body_refs, _ = _class_parts_refs(node)
        return header_refs | body_refs

    if _TYPE_ALIAS_NODE is not None and isinstance(node, _TYPE_ALIAS_NODE):
        tp_refs, tp_names = _free_refs_in_type_params(node)
        val_refs = _free_refs(node.value, in_annotation=True) - tp_names
        return tp_refs | val_refs

    if isinstance(node, ast.ExceptHandler):
        refs = _free_refs(node.type) if node.type is not None else set()
        body_refs: Set[str] = set()
        for stmt in node.body:
            body_refs |= _free_refs(stmt)
        if node.name:
            body_refs.discard(node.name)
        return refs | body_refs

    refs = set()
    for child in ast.iter_child_nodes(node):
        refs |= _free_refs(child, in_annotation=in_annotation)
    return refs


def _extract_string_sequence(node: ast.AST) -> Set[str]:
    names: Set[str] = set()
    if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
        for elt in node.elts:
            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                names.add(elt.value)
    elif isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        names |= _extract_string_sequence(node.left)
        names |= _extract_string_sequence(node.right)
    return names


def _extract_dunder_all_names(stmts: Iterable[ast.stmt]) -> Set[str]:
    names: Set[str] = set()
    for stmt in stmts:
        if isinstance(stmt, ast.Assign):
            if any(
                isinstance(t, ast.Name) and t.id == "__all__"
                for t in stmt.targets
            ):
                names |= _extract_string_sequence(stmt.value)
        elif isinstance(stmt, ast.AnnAssign):
            if (
                isinstance(stmt.target, ast.Name)
                and stmt.target.id == "__all__"
                and stmt.value is not None
            ):
                names |= _extract_string_sequence(stmt.value)
        elif isinstance(stmt, ast.AugAssign):
            if isinstance(stmt.target, ast.Name) and stmt.target.id == "__all__":
                names |= _extract_string_sequence(stmt.value)
        elif isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
            call = stmt.value
            if (
                isinstance(call.func, ast.Attribute)
                and isinstance(call.func.value, ast.Name)
                and call.func.value.id == "__all__"
                and len(call.args) == 1
            ):
                if call.func.attr == "append":
                    arg = call.args[0]
                    if isinstance(arg, ast.Constant) and isinstance(
                        arg.value, str
                    ):
                        names.add(arg.value)
                elif call.func.attr == "extend":
                    names |= _extract_string_sequence(call.args[0])
        elif isinstance(stmt, (ast.If, ast.For, ast.AsyncFor, ast.While)):
            names |= _extract_dunder_all_names(stmt.body)
            names |= _extract_dunder_all_names(stmt.orelse)
        elif isinstance(stmt, (ast.With, ast.AsyncWith)):
            names |= _extract_dunder_all_names(stmt.body)
        elif isinstance(stmt, _TRY_NODES):
            names |= _extract_dunder_all_names(stmt.body)
            for h in stmt.handlers:
                names |= _extract_dunder_all_names(h.body)
            names |= _extract_dunder_all_names(stmt.orelse)
            names |= _extract_dunder_all_names(stmt.finalbody)
        elif _MATCH_NODE is not None and isinstance(stmt, _MATCH_NODE):
            for case in stmt.cases:
                names |= _extract_dunder_all_names(case.body)
    return names


def _is_prunable_private_func(stmt: ast.stmt) -> bool:
    return (
        isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
        and stmt.name.startswith("_")
        and stmt.name not in _PRESERVED_DUNDER_FUNCS
    )


def _filter_import_stmt(
    stmt: ast.stmt,
    scope_refs: Set[str],
    module_refs: Set[str],
    is_module_scope: bool,
    global_names: Set[str],
) -> Optional[ast.stmt]:
    if isinstance(stmt, ast.ImportFrom) and stmt.module == "__future__":
        return stmt
    if not isinstance(stmt, (ast.Import, ast.ImportFrom)):
        return stmt

    kept_aliases: List[ast.alias] = []
    for alias in stmt.names:
        if alias.name == "*":
            kept_aliases.append(alias)
            continue
        bound = _import_bound_name(stmt, alias)
        if is_module_scope:
            if bound in module_refs:
                kept_aliases.append(alias)
        else:
            if bound in scope_refs or (
                bound in global_names and bound in module_refs
            ):
                kept_aliases.append(alias)

    if not kept_aliases:
        return None
    stmt.names = kept_aliases
    return stmt


def _prune_class_body_functions(
    stmts: List[ast.stmt], module_refs: Set[str]
) -> None:
    for stmt in stmts:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _prune_function_imports(stmt, module_refs)
        elif isinstance(stmt, ast.ClassDef):
            _prune_class_body_functions(stmt.body, module_refs)
        elif isinstance(stmt, (ast.If, ast.For, ast.AsyncFor, ast.While)):
            _prune_class_body_functions(stmt.body, module_refs)
            _prune_class_body_functions(stmt.orelse, module_refs)
        elif isinstance(stmt, (ast.With, ast.AsyncWith)):
            _prune_class_body_functions(stmt.body, module_refs)
        elif isinstance(stmt, _TRY_NODES):
            _prune_class_body_functions(stmt.body, module_refs)
            for h in stmt.handlers:
                _prune_class_body_functions(h.body, module_refs)
            _prune_class_body_functions(stmt.orelse, module_refs)
            _prune_class_body_functions(stmt.finalbody, module_refs)
        elif _MATCH_NODE is not None and isinstance(stmt, _MATCH_NODE):
            for case in stmt.cases:
                _prune_class_body_functions(case.body, module_refs)


def _prune_imports_in_stmts(
    stmts: List[ast.stmt],
    scope_refs: Set[str],
    module_refs: Set[str],
    is_module_scope: bool,
    global_names: Set[str],
    allow_empty: bool = False,
) -> List[ast.stmt]:
    new_stmts: List[ast.stmt] = []
    for stmt in stmts:
        if isinstance(stmt, (ast.Import, ast.ImportFrom)):
            filtered = _filter_import_stmt(
                stmt, scope_refs, module_refs, is_module_scope, global_names
            )
            if filtered is not None:
                new_stmts.append(filtered)
            continue

        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _prune_function_imports(stmt, module_refs)
            new_stmts.append(stmt)
            continue

        if isinstance(stmt, ast.ClassDef):
            _prune_class_body_functions(stmt.body, module_refs)
            new_stmts.append(stmt)
            continue

        if isinstance(stmt, (ast.If, ast.For, ast.AsyncFor, ast.While)):
            stmt.body = _prune_imports_in_stmts(
                stmt.body,
                scope_refs,
                module_refs,
                is_module_scope,
                global_names,
                allow_empty=False,
            )
            if stmt.orelse:
                stmt.orelse = _prune_imports_in_stmts(
                    stmt.orelse,
                    scope_refs,
                    module_refs,
                    is_module_scope,
                    global_names,
                    allow_empty=True,
                )
            new_stmts.append(stmt)
            continue

        if isinstance(stmt, (ast.With, ast.AsyncWith)):
            stmt.body = _prune_imports_in_stmts(
                stmt.body,
                scope_refs,
                module_refs,
                is_module_scope,
                global_names,
                allow_empty=False,
            )
            new_stmts.append(stmt)
            continue

        if isinstance(stmt, _TRY_NODES):
            stmt.body = _prune_imports_in_stmts(
                stmt.body,
                scope_refs,
                module_refs,
                is_module_scope,
                global_names,
                allow_empty=False,
            )
            for handler in stmt.handlers:
                handler.body = _prune_imports_in_stmts(
                    handler.body,
                    scope_refs,
                    module_refs,
                    is_module_scope,
                    global_names,
                    allow_empty=False,
                )
            if stmt.orelse:
                stmt.orelse = _prune_imports_in_stmts(
                    stmt.orelse,
                    scope_refs,
                    module_refs,
                    is_module_scope,
                    global_names,
                    allow_empty=True,
                )
            if stmt.finalbody:
                stmt.finalbody = _prune_imports_in_stmts(
                    stmt.finalbody,
                    scope_refs,
                    module_refs,
                    is_module_scope,
                    global_names,
                    allow_empty=bool(stmt.handlers),
                )
            new_stmts.append(stmt)
            continue

        if _MATCH_NODE is not None and isinstance(stmt, _MATCH_NODE):
            for case in stmt.cases:
                case.body = _prune_imports_in_stmts(
                    case.body,
                    scope_refs,
                    module_refs,
                    is_module_scope,
                    global_names,
                    allow_empty=False,
                )
            new_stmts.append(stmt)
            continue

        new_stmts.append(stmt)

    if not new_stmts and not allow_empty:
        return [ast.Pass()]
    return new_stmts


def _prune_function_imports(
    fn_node: ast.AST, module_refs: Set[str]
) -> None:
    assert isinstance(fn_node, (ast.FunctionDef, ast.AsyncFunctionDef))
    _, globals_, _ = _collect_scope_bindings(fn_node.body)
    local_refs: Set[str] = set()
    for stmt in fn_node.body:
        local_refs |= _free_refs(stmt)
    fn_node.body = _prune_imports_in_stmts(
        fn_node.body,
        scope_refs=local_refs,
        module_refs=module_refs,
        is_module_scope=False,
        global_names=globals_,
        allow_empty=False,
    )


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prune unused imports and unreferenced top-level private functions."""
    tree = ast.parse(source_code)

    private_funcs: Dict[str, List[ast.stmt]] = {}
    root_stmts: List[ast.stmt] = []

    for stmt in tree.body:
        if _is_prunable_private_func(stmt):
            assert isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
            private_funcs.setdefault(stmt.name, []).append(stmt)
        elif not isinstance(stmt, (ast.Import, ast.ImportFrom)):
            root_stmts.append(stmt)

    module_refs: Set[str] = _extract_dunder_all_names(tree.body)
    for stmt in root_stmts:
        module_refs |= _free_refs(stmt)

    alive_private_funcs: Set[str] = set()
    queue = list(module_refs & private_funcs.keys())
    while queue:
        fn_name = queue.pop()
        if fn_name in alive_private_funcs:
            continue
        alive_private_funcs.add(fn_name)
        for fn_node in private_funcs[fn_name]:
            fn_refs = _free_refs(fn_node)
            module_refs |= fn_refs
            for name in fn_refs:
                if name in private_funcs and name not in alive_private_funcs:
                    queue.append(name)

    tree.body = [
        stmt
        for stmt in tree.body
        if not (
            _is_prunable_private_func(stmt)
            and stmt.name not in alive_private_funcs
        )
    ]

    tree.body = _prune_imports_in_stmts(
        tree.body,
        scope_refs=module_refs,
        module_refs=module_refs,
        is_module_scope=True,
        global_names=set(),
        allow_empty=True,
    )

    ast.fix_missing_locations(tree)
    return ast.unparse(tree)
