from __future__ import annotations

import fnmatch
from typing import Any

_REQUIRED_REQUEST_STR_FIELDS = (
    "subject_id",
    "tenant_id",
    "resource_tenant_id",
    "action",
    "resource",
)
_REQUIRED_POLICY_LIST_FIELDS = ("roles", "actions", "resources")
_VALID_EFFECTS = frozenset({"allow", "deny"})


def _is_non_empty_str(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _is_non_empty_str_list(value: Any) -> bool:
    return isinstance(value, list) and bool(value) and all(_is_non_empty_str(item) for item in value)


def _is_scalar(value: Any) -> bool:
    return value is None or isinstance(value, (str, int, float, bool))


def _is_valid_condition_value(value: Any) -> bool:
    if _is_scalar(value):
        return True
    if isinstance(value, list):
        return all(_is_scalar(item) for item in value)
    return False


def _scalar_equals(actual: Any, expected: Any) -> bool:
    if not _is_scalar(actual):
        return False
    if isinstance(actual, bool) != isinstance(expected, bool):
        return False
    return actual == expected


def _is_valid_request(request: Any) -> bool:
    if not isinstance(request, dict):
        return False
    for field in _REQUIRED_REQUEST_STR_FIELDS:
        if field not in request or not _is_non_empty_str(request[field]):
            return False
    if "roles" not in request or not _is_non_empty_str_list(request["roles"]):
        return False
    if "context" not in request or not isinstance(request["context"], dict):
        return False
    return True


def _is_valid_policy(policy: Any) -> bool:
    if not isinstance(policy, dict):
        return False
    effect = policy.get("effect")
    if not isinstance(effect, str) or effect not in _VALID_EFFECTS:
        return False
    if "tenant" not in policy or not _is_non_empty_str(policy["tenant"]):
        return False
    for field in _REQUIRED_POLICY_LIST_FIELDS:
        if field not in policy or not _is_non_empty_str_list(policy[field]):
            return False
    if "conditions" in policy:
        conditions = policy["conditions"]
        if not isinstance(conditions, dict):
            return False
        for key, expected in conditions.items():
            if not _is_non_empty_str(key) or not _is_valid_condition_value(expected):
                return False
    return True


def _conditions_match(context: dict[str, Any], conditions: dict[str, Any]) -> bool:
    for key, expected in conditions.items():
        if key not in context:
            return False
        actual = context[key]
        if isinstance(expected, list):
            if not any(_scalar_equals(actual, item) for item in expected):
                return False
        elif not _scalar_equals(actual, expected):
            return False
    return True


def _policy_matches(request: dict[str, Any], policy: dict[str, Any]) -> bool:
    policy_tenant = policy["tenant"]
    if policy_tenant != "*" and policy_tenant != request["tenant_id"]:
        return False

    policy_roles = set(policy["roles"])
    if "*" not in policy_roles and not any(role in policy_roles for role in request["roles"]):
        return False

    request_action = request["action"]
    if not any(fnmatch.fnmatchcase(request_action, pattern) for pattern in policy["actions"]):
        return False

    request_resource = request["resource"]
    if not any(fnmatch.fnmatchcase(request_resource, pattern) for pattern in policy["resources"]):
        return False

    conditions = policy.get("conditions")
    if conditions and not _conditions_match(request["context"], conditions):
        return False

    return True


def authorize(request: dict, policies: list[dict]) -> bool:
    if not _is_valid_request(request):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list):
        return False

    if not all(_is_valid_policy(policy) for policy in policies):
        return False

    matched_allow = False
    for policy in policies:
        if _policy_matches(request, policy):
            if policy["effect"] == "deny":
                return False
            matched_allow = True

    return matched_allow
