from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
import re

_REQUIRED_KEYS = frozenset({"event_id", "payment_id", "sequence", "type", "amount"})
_SUPPORTED_TYPES = frozenset({"authorized", "captured", "refunded", "reversed"})
_AMOUNT_PATTERN = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_ZERO = Decimal("0.00")
_CENT = Decimal("0.01")


@dataclass(frozen=True)
class _Event:
    event_id: str
    payment_id: str
    sequence: int
    event_type: str
    amount: Decimal


@dataclass(frozen=True)
class _PaymentState:
    authorized: Decimal
    captured: Decimal
    refunded: Decimal
    reversed: Decimal
    next_sequence: int

    @property
    def available_to_capture(self) -> Decimal:
        return self.authorized - self.captured

    @property
    def merchant_balance(self) -> Decimal:
        return self.captured - self.refunded - self.reversed

    def to_dict(self) -> dict[str, str | int]:
        return {
            "authorized": f"{self.authorized:.2f}",
            "captured": f"{self.captured:.2f}",
            "refunded": f"{self.refunded:.2f}",
            "reversed": f"{self.reversed:.2f}",
            "available_to_capture": f"{self.available_to_capture:.2f}",
            "merchant_balance": f"{self.merchant_balance:.2f}",
            "next_sequence": self.next_sequence,
        }


class PaymentLedger:
    __slots__ = ("_states", "_buffers", "_events_by_id")

    def __init__(self) -> None:
        self._states: dict[str, _PaymentState] = {}
        self._buffers: dict[str, dict[int, _Event]] = {}
        self._events_by_id: dict[str, _Event] = {}

    def apply(self, event: dict) -> str:
        parsed = self._parse_event(event)

        existing = self._events_by_id.get(parsed.event_id)
        if existing is not None:
            if existing == parsed:
                return "duplicate"
            raise ValueError(f"event_id {parsed.event_id!r} reused with different content")

        current_state = self._states.get(parsed.payment_id)
        next_sequence = 1 if current_state is None else current_state.next_sequence
        payment_buffer = self._buffers.get(parsed.payment_id)

        if parsed.sequence < next_sequence:
            raise ValueError(
                f"sequence {parsed.sequence} already applied for payment {parsed.payment_id!r}"
            )

        if payment_buffer is not None and parsed.sequence in payment_buffer:
            raise ValueError(
                f"sequence {parsed.sequence} already buffered for payment {parsed.payment_id!r}"
            )

        if parsed.sequence > next_sequence:
            if payment_buffer is None:
                payment_buffer = {}
                self._buffers[parsed.payment_id] = payment_buffer
            payment_buffer[parsed.sequence] = parsed
            self._events_by_id[parsed.event_id] = parsed
            return "buffered"

        to_apply = [parsed]
        drained_sequences: list[int] = []
        seq = next_sequence + 1
        if payment_buffer is not None:
            while seq in payment_buffer:
                to_apply.append(payment_buffer[seq])
                drained_sequences.append(seq)
                seq += 1

        candidate_state = current_state
        for ev in to_apply:
            candidate_state = self._transition(candidate_state, ev)

        assert candidate_state is not None
        self._states[parsed.payment_id] = candidate_state
        self._events_by_id[parsed.event_id] = parsed
        if payment_buffer is not None and drained_sequences:
            for drained_seq in drained_sequences:
                del payment_buffer[drained_seq]
            if not payment_buffer:
                del self._buffers[parsed.payment_id]
        return "applied"

    def state(self, payment_id: str) -> dict[str, str | int] | None:
        if not isinstance(payment_id, str):
            return None
        payment_state = self._states.get(payment_id)
        if payment_state is None:
            return None
        return payment_state.to_dict()

    def snapshot(self) -> dict[str, dict[str, str | int]]:
        return {
            payment_id: self._states[payment_id].to_dict()
            for payment_id in sorted(self._states)
        }

    @staticmethod
    def _parse_event(event: object) -> _Event:
        if not isinstance(event, Mapping):
            raise ValueError("event must be a mapping")
        if event.keys() != _REQUIRED_KEYS:
            raise ValueError("event must contain exactly the required fields")

        event_id = event["event_id"]
        if not isinstance(event_id, str) or not event_id.strip():
            raise ValueError("event_id must be a non-empty string")

        payment_id = event["payment_id"]
        if not isinstance(payment_id, str) or not payment_id.strip():
            raise ValueError("payment_id must be a non-empty string")

        sequence = event["sequence"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise ValueError("sequence must be a positive integer")

        event_type = event["type"]
        if not isinstance(event_type, str) or event_type not in _SUPPORTED_TYPES:
            raise ValueError(f"unsupported event type: {event_type!r}")

        amount_raw = event["amount"]
        if not isinstance(amount_raw, str) or _AMOUNT_PATTERN.fullmatch(amount_raw) is None:
            raise ValueError(
                "amount must be a positive decimal string with at most two fractional digits"
            )
        try:
            amount = Decimal(amount_raw).quantize(_CENT)
        except InvalidOperation as exc:
            raise ValueError("invalid decimal amount") from exc

        if amount <= _ZERO:
            raise ValueError("amount must be positive")

        return _Event(
            event_id=event_id,
            payment_id=payment_id,
            sequence=sequence,
            event_type=event_type,
            amount=amount,
        )

    @staticmethod
    def _transition(current: _PaymentState | None, event: _Event) -> _PaymentState:
        if current is None:
            if event.sequence != 1 or event.event_type != "authorized":
                raise ValueError("sequence 1 must authorize the payment")
            return _PaymentState(
                authorized=event.amount,
                captured=_ZERO,
                refunded=_ZERO,
                reversed=_ZERO,
                next_sequence=2,
            )

        if event.sequence != current.next_sequence:
            raise ValueError("out-of-order transition")

        if event.event_type == "authorized":
            raise ValueError("payment is already authorized")

        if event.event_type == "captured":
            new_captured = current.captured + event.amount
            if new_captured > current.authorized:
                raise ValueError("capture exceeds authorized amount")
            return _PaymentState(
                authorized=current.authorized,
                captured=new_captured,
                refunded=current.refunded,
                reversed=current.reversed,
                next_sequence=current.next_sequence + 1,
            )

        remaining_settled = current.merchant_balance
        if event.amount > remaining_settled:
            raise ValueError(f"{event.event_type} exceeds remaining settled balance")

        if event.event_type == "refunded":
            return _PaymentState(
                authorized=current.authorized,
                captured=current.captured,
                refunded=current.refunded + event.amount,
                reversed=current.reversed,
                next_sequence=current.next_sequence + 1,
            )

        if event.event_type == "reversed":
            return _PaymentState(
                authorized=current.authorized,
                captured=current.captured,
                refunded=current.refunded,
                reversed=current.reversed + event.amount,
                next_sequence=current.next_sequence + 1,
            )

        raise ValueError(f"unsupported event type: {event.event_type!r}")
