from __future__ import annotations

import asyncio
from collections import deque
import heapq
import itertools
from typing import Any, Callable, Optional


class AsyncWorkerPool:
    """Bounded asynchronous worker pool with priority scheduling."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be a positive integer")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be >= 0")

        self._concurrency = concurrency
        self._max_queue_size = max_queue_size

        self._heap: list[
            tuple[
                int,
                int,
                Callable[..., Any],
                tuple[Any, ...],
                dict[str, Any],
                asyncio.Future[Any],
            ]
        ] = []
        self._counter = itertools.count()

        self._getters: deque[asyncio.Future[None]] = deque()
        self._putters: deque[asyncio.Future[None]] = deque()

        self._workers: list[asyncio.Task[None]] = []
        self._active_tasks: set[asyncio.Task[Any]] = set()
        self._active_count: int = 0

        self._shutting_down: bool = False
        self._force_stop: bool = False
        self._idle_event: Optional[asyncio.Event] = None

    def _get_idle_event(self) -> asyncio.Event:
        if self._idle_event is None:
            self._idle_event = asyncio.Event()
            if not self._heap and self._active_count == 0:
                self._idle_event.set()
        return self._idle_event

    def _is_full(self) -> bool:
        return self._max_queue_size > 0 and len(self._heap) >= self._max_queue_size

    @staticmethod
    def _wakeup_next(waiters: deque[asyncio.Future[None]]) -> None:
        while waiters:
            waiter = waiters.popleft()
            if not waiter.done():
                waiter.set_result(None)
                return

    @staticmethod
    def _wakeup_all(waiters: deque[asyncio.Future[None]]) -> None:
        while waiters:
            waiter = waiters.popleft()
            if not waiter.done():
                waiter.set_result(None)

    async def start(self) -> None:
        """Spawn worker tasks if the pool has not been started yet."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._workers:
            return
        self._get_idle_event()
        self._workers = [
            asyncio.create_task(self._worker()) for _ in range(self._concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future[Any]:
        """Enqueue a coroutine function for execution by the pool workers."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()

        while self._is_full():
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")
            putter = loop.create_future()
            self._putters.append(putter)
            try:
                await putter
            except BaseException:
                putter.cancel()
                try:
                    self._putters.remove(putter)
                except ValueError:
                    pass
                if not self._shutting_down and not self._is_full():
                    self._wakeup_next(self._putters)
                raise

        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        future: asyncio.Future[Any] = loop.create_future()
        seq = next(self._counter)
        heapq.heappush(self._heap, (-priority, seq, coro_func, args, kwargs, future))
        self._get_idle_event().clear()
        self._wakeup_next(self._getters)
        return future

    async def _worker(self) -> None:
        loop = asyncio.get_running_loop()
        while True:
            while not self._heap:
                if self._shutting_down:
                    return
                getter = loop.create_future()
                self._getters.append(getter)
                try:
                    await getter
                except BaseException:
                    getter.cancel()
                    try:
                        self._getters.remove(getter)
                    except ValueError:
                        pass
                    if self._heap and not self._force_stop:
                        self._wakeup_next(self._getters)
                    raise

            if self._force_stop:
                return

            _, _, coro_func, args, kwargs, future = heapq.heappop(self._heap)
            self._active_count += 1
            self._wakeup_next(self._putters)

            task: Optional[asyncio.Task[Any]] = None
            on_future_done: Optional[Callable[[asyncio.Future[Any]], None]] = None

            try:
                if future.done():
                    continue

                coro = coro_func(*args, **kwargs)
                if asyncio.iscoroutine(coro):
                    task = asyncio.create_task(coro)
                else:
                    async def _await_value(awaitable: Any) -> Any:
                        return await awaitable

                    task = asyncio.create_task(_await_value(coro))

                self._active_tasks.add(task)

                def _on_future_done(
                    f: asyncio.Future[Any],
                    t: asyncio.Task[Any] = task,
                ) -> None:
                    if f.cancelled() and not t.done():
                        t.cancel()

                on_future_done = _on_future_done
                future.add_done_callback(on_future_done)

                try:
                    result = await task
                except asyncio.CancelledError:
                    if not future.done():
                        future.cancel()
                    if self._force_stop or not task.cancelled():
                        raise
                except Exception as exc:
                    if not future.done():
                        future.set_exception(exc)
                else:
                    if not future.done():
                        future.set_result(result)
            except asyncio.CancelledError:
                if task is not None and not task.done():
                    task.cancel()
                    try:
                        await task
                    except BaseException:
                        pass
                if not future.done():
                    future.cancel()
                raise
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            finally:
                if on_future_done is not None:
                    future.remove_done_callback(on_future_done)
                if task is not None:
                    self._active_tasks.discard(task)
                self._active_count -= 1
                if not self._heap and self._active_count == 0:
                    self._get_idle_event().set()

    def _cancel_queued(self) -> None:
        while self._heap:
            _, _, _, _, _, future = heapq.heappop(self._heap)
            if not future.done():
                future.cancel()

    async def _force_shutdown(self, timeout: Optional[float]) -> None:
        self._force_stop = True
        self._cancel_queued()
        self._wakeup_all(self._getters)
        self._wakeup_all(self._putters)

        for task in list(self._active_tasks):
            if not task.done():
                task.cancel()

        workers = list(self._workers)
        for worker in workers:
            if not worker.done():
                worker.cancel()

        if workers:
            done, _ = await asyncio.wait(workers, timeout=timeout)
            for worker in done:
                if not worker.cancelled():
                    worker.exception()

        self._workers.clear()
        if not self._heap and self._active_count == 0:
            self._get_idle_event().set()

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shut down the pool, optionally draining queued tasks."""
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must be >= 0 or None")

        self._shutting_down = True
        self._wakeup_all(self._putters)

        if not drain:
            await self._force_shutdown(timeout=timeout)
            return

        self._wakeup_all(self._getters)

        if not self._workers:
            self._cancel_queued()
            self._get_idle_event().set()
            return

        loop = asyncio.get_running_loop()
        deadline = loop.time() + timeout if timeout is not None else None
        idle_event = self._get_idle_event()

        if not idle_event.is_set():
            try:
                await asyncio.wait_for(idle_event.wait(), timeout=timeout)
            except asyncio.TimeoutError:
                grace = 0.05 if timeout is None else min(0.05, timeout)
                await self._force_shutdown(timeout=grace)
                return

        self._wakeup_all(self._getters)
        workers = list(self._workers)

        if workers:
            remaining = (
                max(0.0, deadline - loop.time()) if deadline is not None else None
            )
            done, pending = await asyncio.wait(workers, timeout=remaining)
            for worker in pending:
                worker.cancel()
            if pending:
                await asyncio.wait(pending, timeout=0.05)
            for worker in done:
                if not worker.cancelled():
                    worker.exception()

        self._workers.clear()
