import fnmatch


def _is_non_empty_str(value: object) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _is_scalar(value: object) -> bool:
    return isinstance(value, (str, int, float, bool))


def _scalar_equal(a: object, b: object) -> bool:
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    return a == b


def _is_valid_request(request: object) -> bool:
    if not isinstance(request, dict):
        return False

    for field in ("subject_id", "tenant_id", "resource_tenant_id", "action", "resource"):
        if not _is_non_empty_str(request.get(field)):
            return False

    roles = request.get("roles")
    if not isinstance(roles, list) or not roles:
        return False
    if not all(_is_non_empty_str(role) for role in roles):
        return False

    context = request.get("context")
    if not isinstance(context, dict):
        return False
    if not all(isinstance(key, str) for key in context):
        return False

    return True


def _is_valid_policy(policy: object) -> bool:
    if not isinstance(policy, dict):
        return False

    effect = policy.get("effect")
    if not isinstance(effect, str) or effect not in ("allow", "deny"):
        return False

    if not _is_non_empty_str(policy.get("tenant")):
        return False

    for field in ("roles", "actions", "resources"):
        items = policy.get(field)
        if not isinstance(items, list) or not items:
            return False
        if not all(_is_non_empty_str(item) for item in items):
            return False

    if "conditions" in policy:
        conditions = policy["conditions"]
        if not isinstance(conditions, dict):
            return False
        for key, value in conditions.items():
            if not _is_non_empty_str(key):
                return False
            if isinstance(value, list):
                if not all(_is_scalar(item) for item in value):
                    return False
            elif not _is_scalar(value):
                return False

    return True


def _policy_matches(policy: dict, request: dict) -> bool:
    policy_tenant = policy["tenant"]
    if policy_tenant != "*" and policy_tenant != request["tenant_id"]:
        return False

    request_roles = set(request["roles"])
    if not any(role == "*" or role in request_roles for role in policy["roles"]):
        return False

    action = request["action"]
    if not any(fnmatch.fnmatchcase(action, pattern) for pattern in policy["actions"]):
        return False

    resource = request["resource"]
    if not any(fnmatch.fnmatchcase(resource, pattern) for pattern in policy["resources"]):
        return False

    conditions = policy.get("conditions")
    if conditions:
        context = request["context"]
        for key, expected in conditions.items():
            if key not in context:
                return False
            actual = context[key]
            if isinstance(expected, list):
                if not any(_scalar_equal(actual, item) for item in expected):
                    return False
            elif not _scalar_equal(actual, expected):
                return False

    return True


def authorize(request: dict, policies: list[dict]) -> bool:
    if not _is_valid_request(request):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list):
        return False

    for policy in policies:
        if not _is_valid_policy(policy):
            return False

    allowed = False
    for policy in policies:
        if _policy_matches(policy, request):
            if policy["effect"] == "deny":
                return False
            allowed = True

    return allowed
