from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from decimal import Decimal
import re


_REQUIRED_FIELDS = frozenset(
    {"event_id", "payment_id", "sequence", "type", "amount"}
)
_SUPPORTED_TYPES = frozenset({"authorized", "captured", "refunded", "reversed"})
_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_ZERO = Decimal("0.00")


@dataclass(frozen=True, slots=True)
class _Event:
    event_id: str
    payment_id: str
    sequence: int
    type: str
    amount: Decimal

    def content_key(self) -> tuple[str, int, str, Decimal]:
        return (self.payment_id, self.sequence, self.type, self.amount)


@dataclass(frozen=True, slots=True)
class _PaymentState:
    authorized: Decimal
    captured: Decimal = _ZERO
    refunded: Decimal = _ZERO
    reversed: Decimal = _ZERO
    next_sequence: int = 2

    def to_dict(self) -> dict[str, str | int]:
        available_to_capture = self.authorized - self.captured
        merchant_balance = self.captured - self.refunded - self.reversed
        return {
            "authorized": f"{self.authorized:.2f}",
            "captured": f"{self.captured:.2f}",
            "refunded": f"{self.refunded:.2f}",
            "reversed": f"{self.reversed:.2f}",
            "available_to_capture": f"{available_to_capture:.2f}",
            "merchant_balance": f"{merchant_balance:.2f}",
            "next_sequence": self.next_sequence,
        }


class PaymentLedger:
    """In-memory payment ledger with ordered sequence processing and out-of-order buffering."""

    def __init__(self) -> None:
        self._payments: dict[str, _PaymentState] = {}
        self._buffers: dict[str, dict[int, _Event]] = {}
        self._events: dict[str, _Event] = {}

    @staticmethod
    def _parse_event(event: dict) -> _Event:
        if not isinstance(event, Mapping):
            raise ValueError("event must be a mapping")
        if set(event.keys()) != _REQUIRED_FIELDS:
            raise ValueError("event must contain exactly the required fields")

        event_id = event["event_id"]
        if not isinstance(event_id, str) or not event_id.strip():
            raise ValueError("event_id must be a non-empty string")

        payment_id = event["payment_id"]
        if not isinstance(payment_id, str) or not payment_id.strip():
            raise ValueError("payment_id must be a non-empty string")

        sequence = event["sequence"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise ValueError("sequence must be a positive integer")

        event_type = event["type"]
        if not isinstance(event_type, str) or event_type not in _SUPPORTED_TYPES:
            raise ValueError("unsupported event type")

        raw_amount = event["amount"]
        if not isinstance(raw_amount, str) or _AMOUNT_RE.fullmatch(raw_amount) is None:
            raise ValueError(
                "amount must be a positive decimal string with at most two fractional digits"
            )

        amount = Decimal(raw_amount)
        if amount <= _ZERO:
            raise ValueError("amount must be positive")

        return _Event(
            event_id=event_id,
            payment_id=payment_id,
            sequence=sequence,
            type=event_type,
            amount=amount,
        )

    @staticmethod
    def _advance_state(current: _PaymentState | None, event: _Event) -> _PaymentState:
        if current is None:
            if event.sequence != 1 or event.type != "authorized":
                raise ValueError("sequence 1 must authorize the payment")
            return _PaymentState(authorized=event.amount, next_sequence=2)

        if event.sequence != current.next_sequence:
            raise ValueError("event sequence out of order")

        if event.type == "authorized":
            raise ValueError("payment is already authorized")

        if event.type == "captured":
            new_captured = current.captured + event.amount
            if new_captured > current.authorized:
                raise ValueError("capture exceeds authorized amount")
            return _PaymentState(
                authorized=current.authorized,
                captured=new_captured,
                refunded=current.refunded,
                reversed=current.reversed,
                next_sequence=current.next_sequence + 1,
            )

        remaining_settled = current.captured - current.refunded - current.reversed
        if event.amount > remaining_settled:
            raise ValueError(f"{event.type} exceeds remaining settled amount")

        if event.type == "refunded":
            return _PaymentState(
                authorized=current.authorized,
                captured=current.captured,
                refunded=current.refunded + event.amount,
                reversed=current.reversed,
                next_sequence=current.next_sequence + 1,
            )

        return _PaymentState(
            authorized=current.authorized,
            captured=current.captured,
            refunded=current.refunded,
            reversed=current.reversed + event.amount,
            next_sequence=current.next_sequence + 1,
        )

    def apply(self, event: dict) -> str:
        """Validate and apply or buffer an immutable payment event."""
        parsed = self._parse_event(event)

        existing = self._events.get(parsed.event_id)
        if existing is not None:
            if existing.content_key() == parsed.content_key():
                return "duplicate"
            raise ValueError("event_id reused with different content")

        current_state = self._payments.get(parsed.payment_id)
        expected_seq = 1 if current_state is None else current_state.next_sequence
        payment_buffer = self._buffers.get(parsed.payment_id)

        if parsed.sequence < expected_seq:
            raise ValueError("sequence already applied with different content")
        if payment_buffer is not None and parsed.sequence in payment_buffer:
            raise ValueError("sequence already buffered with different content")

        if parsed.sequence > expected_seq:
            if payment_buffer is None:
                payment_buffer = {}
                self._buffers[parsed.payment_id] = payment_buffer
            payment_buffer[parsed.sequence] = parsed
            self._events[parsed.event_id] = parsed
            return "buffered"

        # Sequence matches expected_seq: apply and drain consecutive buffered events atomically.
        working_state = self._advance_state(current_state, parsed)
        drained_sequences: list[int] = []

        if payment_buffer:
            seq = working_state.next_sequence
            while seq in payment_buffer:
                buffered_event = payment_buffer[seq]
                working_state = self._advance_state(working_state, buffered_event)
                drained_sequences.append(seq)
                seq = working_state.next_sequence

        self._payments[parsed.payment_id] = working_state
        self._events[parsed.event_id] = parsed
        if payment_buffer is not None and drained_sequences:
            for seq in drained_sequences:
                del payment_buffer[seq]
            if not payment_buffer:
                del self._buffers[parsed.payment_id]

        return "applied"

    def state(self, payment_id: str) -> dict | None:
        """Return a fresh state dictionary for payment_id, or None if not yet applied."""
        if not isinstance(payment_id, str):
            return None
        payment_state = self._payments.get(payment_id)
        if payment_state is None:
            return None
        return payment_state.to_dict()

    def snapshot(self) -> dict:
        """Return fresh state dictionaries keyed by sorted payment_id."""
        return {
            payment_id: self._payments[payment_id].to_dict()
            for payment_id in sorted(self._payments)
        }
