from collections.abc import Callable
from typing import Any


class RetryableError(Exception):
    """Error indicating a step or compensation failed transiently and may be retried."""


class FatalError(Exception):
    """Error indicating a permanent failure that triggers compensation."""


class CrashError(Exception):
    """Error indicating an abrupt crash that halts execution immediately."""


class SagaOrchestrator:
    """Orchestrates multi-step sagas with retries, reverse compensation, and crash recovery."""

    def __init__(
        self,
        executor: Callable[[str], Any],
        compensator: Callable[[str], Any],
        max_retries: int = 2,
        journal: dict | None = None,
    ) -> None:
        if not callable(executor):
            raise TypeError("executor must be callable")
        if not callable(compensator):
            raise TypeError("compensator must be callable")
        if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
            raise ValueError("max_retries must be a non-negative integer")
        if journal is not None and not isinstance(journal, dict):
            raise TypeError("journal must be a dict or None")

        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = journal if journal is not None else {}

    def run(self, saga_id: str, steps: list[str]) -> str:
        """Start or resume a saga for the given saga_id and ordered step plan."""
        validated_steps = self._validate_inputs(saga_id, steps)
        entry = self.journal.get(saga_id)
        if entry is None:
            entry = {
                "steps": validated_steps,
                "status": "running",
                "completed": [],
                "compensated": [],
            }
            self.journal[saga_id] = entry
        elif entry.get("steps") != validated_steps:
            raise ValueError(f"Step plan changed for existing saga {saga_id!r}")

        return self._drive(entry, validated_steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        """Recover an existing saga from durable progress stored in the journal."""
        validated_steps = self._validate_inputs(saga_id, steps)
        if saga_id not in self.journal:
            raise ValueError(f"Unknown saga {saga_id!r}")
        entry = self.journal[saga_id]
        if entry.get("steps") != validated_steps:
            raise ValueError(f"Step plan changed for existing saga {saga_id!r}")

        return self._drive(entry, validated_steps)

    def _validate_inputs(self, saga_id: str, steps: list[str]) -> list[str]:
        if not isinstance(saga_id, str) or not saga_id.strip():
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, (list, tuple)):
            raise ValueError("steps must be a list of unique non-empty strings")

        validated: list[str] = []
        seen: set[str] = set()
        for step in steps:
            if not isinstance(step, str) or not step.strip():
                raise ValueError("each step must be a non-empty string")
            if step in seen:
                raise ValueError(f"duplicate step {step!r}")
            seen.add(step)
            validated.append(step)
        return validated

    def _drive(self, entry: dict, steps: list[str]) -> str:
        status = entry["status"]
        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"
        if status == "compensating":
            return self._compensate(entry)

        completed_set = set(entry["completed"])
        for step in steps:
            if step in completed_set:
                continue
            try:
                self._call_with_retries(self.executor, step)
            except CrashError:
                raise
            except FatalError:
                entry["status"] = "compensating"
                return self._compensate(entry)

            entry["completed"].append(step)
            completed_set.add(step)

        entry["status"] = "completed"
        return "completed"

    def _compensate(self, entry: dict) -> str:
        compensated_set = set(entry["compensated"])
        for step in reversed(entry["completed"]):
            if step in compensated_set:
                continue
            self._call_with_retries(self.compensator, step)
            entry["compensated"].append(step)
            compensated_set.add(step)

        entry["status"] = "compensated"
        return "compensated"

    def _call_with_retries(self, fn: Callable[[str], Any], step: str) -> None:
        attempts = self.max_retries + 1
        for attempt in range(attempts):
            try:
                fn(step)
                return
            except CrashError:
                raise
            except RetryableError as exc:
                if attempt == attempts - 1:
                    raise FatalError(f"Step {step!r} exhausted {self.max_retries} retries") from exc
            except FatalError:
                raise
            except Exception as exc:
                raise FatalError(f"Step {step!r} failed with unexpected error: {exc}") from exc
