import asyncio
from dataclasses import dataclass, field
import inspect
import itertools
from typing import Any, Callable, Dict, List, Optional, Set, Tuple


@dataclass(order=True)
class _WorkItem:
    neg_priority: float
    seq: int
    future: asyncio.Future = field(compare=False)
    coro_func: Callable[..., Any] = field(compare=False)
    args: Tuple[Any, ...] = field(compare=False)
    kwargs: Dict[str, Any] = field(compare=False)
    cancelled: bool = field(default=False, compare=False)


class AsyncWorkerPool:
    """Asynchronous worker pool with priority scheduling and graceful/forced shutdown."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be >= 0")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size

        self._queue: asyncio.PriorityQueue[_WorkItem] = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._counter = itertools.count()
        self._workers: List[asyncio.Task[None]] = []
        self._active_tasks: Set[asyncio.Task[Any]] = set()
        self._worker_current_job: Dict[asyncio.Task[None], asyncio.Task[Any]] = {}

        self._started: bool = False
        self._shutting_down: bool = False
        self._stopped: bool = False
        self._shutdown_complete: bool = False

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return

        self._started = True
        for i in range(self.concurrency):
            worker = asyncio.create_task(
                self._worker_loop(), name=f"AsyncWorkerPool-worker-{i}"
            )
            self._workers.append(worker)

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function to be executed by the pool workers."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if not callable(coro_func) and not inspect.isawaitable(coro_func):
            raise TypeError(
                "coro_func must be a coroutine function, callable, or awaitable"
            )

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()
        item = _WorkItem(
            neg_priority=-priority,
            seq=next(self._counter),
            future=future,
            coro_func=coro_func,
            args=args,
            kwargs=kwargs,
        )

        await self._queue.put(item)

        if self._shutting_down:
            item.cancelled = True
            try:
                popped = self._queue.get_nowait()
                popped.cancelled = True
                if not popped.future.done():
                    popped.future.cancel()
                if asyncio.iscoroutine(popped.coro_func):
                    popped.coro_func.close()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                pass

            if not future.done():
                future.cancel()
            if asyncio.iscoroutine(coro_func):
                coro_func.close()
            raise RuntimeError("Pool is shutting down")

        return future

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shuts down the worker pool, optionally draining queued tasks."""
        self._shutting_down = True

        if self._shutdown_complete:
            return

        loop = asyncio.get_running_loop()
        deadline = (
            (loop.time() + max(0.0, timeout)) if timeout is not None else None
        )

        if drain:
            if not self._started and not self._queue.empty():
                self._shutting_down = False
                await self.start()
                self._shutting_down = True

            try:
                if deadline is not None:
                    remaining = max(0.0, deadline - loop.time())
                    await asyncio.wait_for(self._queue.join(), timeout=remaining)
                else:
                    await self._queue.join()
            except asyncio.TimeoutError:
                pass

        self._stopped = True
        self._cancel_queued_tasks()
        self._cancel_active_and_workers()

        if self._workers:
            remaining = (
                max(0.0, deadline - loop.time()) if deadline is not None else None
            )
            try:
                if remaining is not None:
                    wait_timeout = remaining if remaining > 0 else 0.05
                    await asyncio.wait_for(
                        asyncio.gather(*self._workers, return_exceptions=True),
                        timeout=wait_timeout,
                    )
                else:
                    await asyncio.gather(*self._workers, return_exceptions=True)
            except asyncio.TimeoutError:
                for worker in self._workers:
                    if not worker.done():
                        worker.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)

        self._cancel_queued_tasks()
        self._shutdown_complete = True

    def _cancel_queued_tasks(self) -> None:
        """Cancels and drains all remaining items in the priority queue."""
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            item.cancelled = True
            if not item.future.done():
                item.future.cancel()
            if asyncio.iscoroutine(item.coro_func):
                item.coro_func.close()
            self._queue.task_done()

    def _cancel_active_and_workers(self) -> None:
        """Cancels all currently executing job tasks and idle worker tasks."""
        for worker in self._workers:
            if worker.done():
                continue
            job_task = self._worker_current_job.get(worker)
            if job_task is not None and not job_task.done():
                job_task.cancel()
            else:
                worker.cancel()

        for job_task in list(self._active_tasks):
            if not job_task.done():
                job_task.cancel()

    async def _worker_loop(self) -> None:
        """Main execution loop for each worker task."""
        current_worker = asyncio.current_task()
        while not self._stopped:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            try:
                if item.cancelled or item.future.cancelled() or self._stopped:
                    if not item.future.done():
                        item.future.cancel()
                    if asyncio.iscoroutine(item.coro_func):
                        item.coro_func.close()
                    continue

                try:
                    if asyncio.iscoroutine(item.coro_func) or isinstance(
                        item.coro_func, asyncio.Future
                    ):
                        awaitable = item.coro_func
                    else:
                        awaitable = item.coro_func(*item.args, **item.kwargs)
                except Exception as exc:
                    if not item.future.done():
                        item.future.set_exception(exc)
                    continue
                except BaseException as exc:
                    if not item.future.done():
                        if isinstance(exc, asyncio.CancelledError):
                            item.future.cancel()
                        else:
                            item.future.set_exception(exc)
                    if isinstance(exc, asyncio.CancelledError) and self._stopped:
                        break
                    continue

                if not inspect.isawaitable(awaitable):
                    if not item.future.done():
                        item.future.set_result(awaitable)
                    continue

                job_task = asyncio.ensure_future(awaitable)
                self._active_tasks.add(job_task)
                if current_worker is not None:
                    self._worker_current_job[current_worker] = job_task

                def _on_future_done(
                    fut: asyncio.Future, jt: asyncio.Task[Any] = job_task
                ) -> None:
                    if fut.cancelled() and not jt.done():
                        jt.cancel()

                item.future.add_done_callback(_on_future_done)

                try:
                    result = await job_task
                except asyncio.CancelledError:
                    if not job_task.done():
                        job_task.cancel()
                        try:
                            await job_task
                        except (asyncio.CancelledError, Exception):
                            pass
                    if not item.future.done():
                        item.future.cancel()
                    if self._stopped:
                        break
                except Exception as exc:
                    if not item.future.done():
                        item.future.set_exception(exc)
                except BaseException as exc:
                    if not item.future.done():
                        item.future.set_exception(exc)
                    raise
                else:
                    if not item.future.done():
                        if self._stopped:
                            item.future.cancel()
                        else:
                            item.future.set_result(result)
                finally:
                    self._active_tasks.discard(job_task)
                    if current_worker is not None:
                        self._worker_current_job.pop(current_worker, None)
            finally:
                if not item.future.done():
                    item.future.cancel()
                self._queue.task_done()

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(
        self,
        exc_type: Optional[type],
        exc_val: Optional[BaseException],
        exc_tb: Any,
    ) -> None:
        if not self._shutdown_complete:
            await self.shutdown(drain=(exc_type is None))
