import fnmatch
from typing import Any


def _is_non_empty_str(value: Any) -> bool:
    return isinstance(value, str) and len(value.strip()) > 0


def _is_non_empty_str_list(value: Any) -> bool:
    return (
        isinstance(value, list)
        and len(value) > 0
        and all(_is_non_empty_str(item) for item in value)
    )


def _is_scalar(value: Any) -> bool:
    return isinstance(value, (str, int, float, bool))


def _scalar_equals(left: Any, right: Any) -> bool:
    if not (_is_scalar(left) and _is_scalar(right)):
        return False
    if isinstance(left, bool) is not isinstance(right, bool):
        return False
    return left == right


def _is_valid_request(request: Any) -> bool:
    if not isinstance(request, dict):
        return False

    required_keys = {
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "roles",
        "action",
        "resource",
        "context",
    }
    if set(request.keys()) != required_keys:
        return False

    if not (
        _is_non_empty_str(request["subject_id"])
        and _is_non_empty_str(request["tenant_id"])
        and _is_non_empty_str(request["resource_tenant_id"])
        and _is_non_empty_str(request["action"])
        and _is_non_empty_str(request["resource"])
    ):
        return False

    if not _is_non_empty_str_list(request["roles"]):
        return False

    context = request["context"]
    if not isinstance(context, dict):
        return False
    if not all(_is_non_empty_str(k) for k in context.keys()):
        return False

    return True


def _is_valid_policy(policy: Any) -> bool:
    if not isinstance(policy, dict):
        return False

    required_keys = {"effect", "tenant", "roles", "actions", "resources"}
    allowed_keys = required_keys | {"conditions"}
    policy_keys = set(policy.keys())

    if not required_keys.issubset(policy_keys) or not policy_keys.issubset(allowed_keys):
        return False

    if policy["effect"] not in ("allow", "deny"):
        return False

    if not _is_non_empty_str(policy["tenant"]):
        return False

    if not (
        _is_non_empty_str_list(policy["roles"])
        and _is_non_empty_str_list(policy["actions"])
        and _is_non_empty_str_list(policy["resources"])
    ):
        return False

    if "conditions" in policy:
        conditions = policy["conditions"]
        if not isinstance(conditions, dict):
            return False
        for key, cond_val in conditions.items():
            if not _is_non_empty_str(key):
                return False
            if isinstance(cond_val, list):
                if len(cond_val) == 0 or not all(_is_scalar(item) for item in cond_val):
                    return False
            elif not _is_scalar(cond_val):
                return False

    return True


def _conditions_match(conditions: dict[str, Any], context: dict[str, Any]) -> bool:
    for key, expected in conditions.items():
        if key not in context:
            return False
        actual = context[key]
        if isinstance(expected, list):
            if not any(_scalar_equals(actual, item) for item in expected):
                return False
        else:
            if not _scalar_equals(actual, expected):
                return False
    return True


def _policy_matches(request: dict[str, Any], policy: dict[str, Any]) -> bool:
    policy_tenant = policy["tenant"]
    if policy_tenant != "*" and policy_tenant != request["tenant_id"]:
        return False

    request_roles = set(request["roles"])
    policy_roles = policy["roles"]
    if "*" not in policy_roles and not any(role in request_roles for role in policy_roles):
        return False

    request_action = request["action"]
    if not any(fnmatch.fnmatchcase(request_action, pat) for pat in policy["actions"]):
        return False

    request_resource = request["resource"]
    if not any(fnmatch.fnmatchcase(request_resource, pat) for pat in policy["resources"]):
        return False

    conditions = policy.get("conditions")
    if conditions and not _conditions_match(conditions, request["context"]):
        return False

    return True


def authorize(request: dict, policies: list[dict]) -> bool:
    if not _is_valid_request(request):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list):
        return False

    for policy in policies:
        if not _is_valid_policy(policy):
            return False

    allowed = False
    for policy in policies:
        if _policy_matches(request, policy):
            if policy["effect"] == "deny":
                return False
            allowed = True

    return allowed
