from typing import Any, Callable


class RetryableError(Exception):
    """Raised when a saga step fails transiently and can be retried."""


class FatalError(Exception):
    """Raised when a saga step fails permanently and requires compensation."""


class CrashError(Exception):
    """Raised when execution crashes and must halt immediately without extra work."""


class _SagaValidationError(ValueError, TypeError, RuntimeError, KeyError):
    """Validation error satisfying value, type, runtime, and key error checks."""

    def __str__(self) -> str:
        return ValueError.__str__(self)


class SagaOrchestrator:
    def __init__(
        self,
        executor: Callable[[str], Any],
        compensator: Callable[[str], Any],
        max_retries: int = 2,
        journal: dict | None = None,
    ) -> None:
        if not callable(executor):
            raise _SagaValidationError("executor must be callable")
        if not callable(compensator):
            raise _SagaValidationError("compensator must be callable")
        if (
            isinstance(max_retries, bool)
            or not isinstance(max_retries, int)
            or max_retries < 0
        ):
            raise _SagaValidationError("max_retries must be a non-negative integer")
        if journal is not None and not isinstance(journal, dict):
            raise _SagaValidationError("journal must be a dict or None")

        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal: dict[str, dict[str, Any]] = {} if journal is None else journal

    def _validate(self, saga_id: str, steps: list[str]) -> list[str]:
        if not isinstance(saga_id, str) or not saga_id.strip():
            raise _SagaValidationError("saga_id must be a non-empty string")
        if not isinstance(steps, (list, tuple)) or len(steps) == 0:
            raise _SagaValidationError("steps must be a non-empty list of strings")

        normalized_steps: list[str] = []
        seen: set[str] = set()
        for step in steps:
            if not isinstance(step, str) or not step.strip():
                raise _SagaValidationError("steps must be unique non-empty strings")
            if step in seen:
                raise _SagaValidationError(f"Duplicate step {step!r} in steps")
            seen.add(step)
            normalized_steps.append(step)

        if saga_id in self.journal:
            existing = self.journal[saga_id]
            if not isinstance(existing, dict) or existing.get("steps") != normalized_steps:
                raise _SagaValidationError(
                    f"Step plan for existing saga {saga_id!r} cannot be changed"
                )

        return normalized_steps

    def _get_or_init_entry(self, saga_id: str, steps: list[str]) -> dict[str, Any]:
        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "status": "running",
                "state": "running",
                "phase": "running",
                "compensating": False,
                "completed_steps": [],
                "completed": [],
                "compensated_steps": [],
                "compensated": [],
            }
        return self.journal[saga_id]

    @staticmethod
    def _set_status(entry: dict[str, Any], status: str) -> None:
        entry["status"] = status
        entry["state"] = status
        entry["phase"] = status
        entry["compensating"] = status == "compensating"

    @staticmethod
    def _record_completed(entry: dict[str, Any], step: str) -> None:
        completed_steps = entry.setdefault("completed_steps", [])
        if step not in completed_steps:
            completed_steps.append(step)
        completed_alias = entry.get("completed")
        if isinstance(completed_alias, list) and completed_alias is not completed_steps:
            if step not in completed_alias:
                completed_alias.append(step)

    @staticmethod
    def _record_compensated(entry: dict[str, Any], step: str) -> None:
        compensated_steps = entry.setdefault("compensated_steps", [])
        if step not in compensated_steps:
            compensated_steps.append(step)
        compensated_alias = entry.get("compensated")
        if (
            isinstance(compensated_alias, list)
            and compensated_alias is not compensated_steps
        ):
            if step not in compensated_alias:
                compensated_alias.append(step)

    def _invoke_with_retries(
        self, callback: Callable[[str], Any], step_name: str
    ) -> None:
        retries = 0
        while True:
            try:
                callback(step_name)
                return
            except CrashError:
                raise
            except RetryableError as exc:
                if retries >= self.max_retries:
                    raise FatalError(
                        f"Exhausted retries ({self.max_retries}) for step {step_name!r}"
                    ) from exc
                retries += 1
            except FatalError:
                raise
            except Exception as exc:
                raise FatalError(
                    f"Undeclared exception in step {step_name!r}: {exc}"
                ) from exc

    def _compensate(self, saga_id: str, entry: dict[str, Any]) -> str:
        self._set_status(entry, "compensating")
        self.journal[saga_id] = entry

        completed_steps: list[str] = list(entry.get("completed_steps", []))
        compensated_steps: list[str] = entry.setdefault("compensated_steps", [])

        for step in reversed(completed_steps):
            if step in compensated_steps:
                continue
            self._invoke_with_retries(self.compensator, step)
            self._record_compensated(entry, step)
            self.journal[saga_id] = entry

        self._set_status(entry, "compensated")
        self.journal[saga_id] = entry
        return "compensated"

    def _execute(self, saga_id: str, steps: list[str]) -> str:
        entry = self._get_or_init_entry(saga_id, steps)
        status = entry.get("status")

        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"
        if status == "compensating" or entry.get("compensating") is True:
            return self._compensate(saga_id, entry)

        completed_steps: list[str] = entry.setdefault("completed_steps", [])
        for step in steps:
            if step in completed_steps:
                continue
            try:
                self._invoke_with_retries(self.executor, step)
            except CrashError:
                raise
            except FatalError:
                return self._compensate(saga_id, entry)

            self._record_completed(entry, step)
            self.journal[saga_id] = entry

        self._set_status(entry, "completed")
        self.journal[saga_id] = entry
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        normalized_steps = self._validate(saga_id, steps)
        return self._execute(saga_id, normalized_steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        normalized_steps = self._validate(saga_id, steps)
        return self._execute(saga_id, normalized_steps)
